"""Bundled asset folders: grunges, damage alphas and decals (generated by realworn/builders/gen_*).

v3 has no shared node groups: every node lives in a material's own RW_Stack::<material>, labelled,
so nothing is appended from an asset .blend.
"""

import os

import bpy

PKG_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
ASSET_DIR = os.path.join(PKG_DIR, "assets")


def remove_unused_groups():
    """Delete RealWorn node groups (stacks, older versions' groups) with no users (Remove All)."""
    removed = 0
    for _ in range(4):  # nested groups free up their children on the next pass
        for g in list(bpy.data.node_groups):
            if g.name.startswith("RW_") and g.users == 0:
                bpy.data.node_groups.remove(g)
                removed += 1
    return removed
